"""Mojo port of `src/names/`, generated by mojo-anything. Import this package where the code
imported the original module."""

from . import _native

import builtins as _builtins


def _call(f, *args):
    try:
        return f(*args)
    except Exception as e:
        # Mojo raises every error as `Exception`; `Name: message` names the exception to raise.
        if type(e) is not Exception:
            raise
        name, sep, message = str(e).partition(": ")
        cls = getattr(_builtins, name, None)
        if not (sep and isinstance(cls, type) and issubclass(cls, BaseException)):
            raise
        # Some builtins take several arguments (`UnicodeDecodeError`): use the nearest base
        # that takes a message alone.
        for base in cls.__mro__:
            try:
                error = base(message)
            except TypeError:
                continue
            raise error from None
        raise


def pick(type, out, port):
    return _call(_native.pick, type, out, port)


def match(case):
    return _call(_native.match, case)


def lengths(items):
    return _call(_native.lengths, items)


def spin(n):
    return _call(_native.spin, n)


# Not ported: these stay in Python and come from the original module.
_KEPT = {
    "total": "names.pick",
    "Box": "names.pick",
}


def __getattr__(name):
    if name in _KEPT:
        import importlib

        try:
            module = importlib.import_module(_KEPT[name])
        except ImportError as error:
            raise AttributeError(
                f"{name!r} stays in Python, in {_KEPT[name]}, which cannot be imported: {error}"
            ) from error
        return getattr(module, name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")


__all__ = ["pick", "match", "lengths", "spin", "total", "Box"]
